function closestKeyGap(root: TreeNode | null): number {
  const vals: number[] = [];
  const stack: (TreeNode | null)[] = [root];
  while (stack.length) {
    const node = stack.pop();
    if (!node) continue;
    vals.push(node.val);
    stack.push(node.left, node.right);
  }
  vals.sort((a, b) => a - b);
  let best = Infinity;
  for (let i = 1; i < vals.length; i++) best = Math.min(best, vals[i] - vals[i - 1]);
  return best;
}

