function closestKeyGap(root: TreeNode | null): number {
  const stack: TreeNode[] = [];
  let cur = root, prev: number | null = null, best = Infinity;
  while (cur || stack.length) {
    while (cur) {
      stack.push(cur);
      cur = cur.left;
    }
    const node = stack.pop()!;
    if (prev !== null) best = Math.min(best, node.val - prev);
    prev = node.val;
    cur = node.right;
  }
  return best;
}

